      : null;

    return {
      id: taskId,
      domain: defaultDomain,
      source: sourceName,
      title: `${candidateId} · ${titleText}`,
      promptContext: {
        candidateId,
        title: titleText,
        files: filesArray,
        fetchedFiles,
        body: section,
        splitDepth,
        mustPreSplit,
        ...(groundingConfidence ? { groundingConfidence } : {}),
      },
    };
  }

  return null;
}

